// Run with `npm test`. Every spreadsheet used here is generated by the test itself (no binary
// fixtures in the repo). ExcelJS builds the input files directly, so the tests do not depend on
// sheet.ts's own writer to make the files it reads.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { crc32, deflateRawSync, inflateRawSync } from 'node:zlib';
import ExcelJS from 'exceljs';
import { checkRows, parseDate, parseNumber, readCsv, readSheet, readTable, writeCsv, writeSheet } from '../src/sheet.ts';

// ------------------------------------------------------------------ helpers

async function book(fill, sheetName = 'Bills') {
  const wb = new ExcelJS.Workbook();
  const ws = wb.addWorksheet(sheetName);
  fill(ws, wb);
  return new Uint8Array(await wb.xlsx.writeBuffer());
}

const bytes = (text) => new TextEncoder().encode(text);

/** Minimal zip reader/writer, to look inside an .xlsx and to damage one on purpose. */
function unzip(file) {
  const b = Buffer.from(file);
  const eocd = b.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  const count = b.readUInt16LE(eocd + 10);
  let pos = b.readUInt32LE(eocd + 16);
  const out = new Map();
  for (let i = 0; i < count; i++) {
    const method = b.readUInt16LE(pos + 10);
    const size = b.readUInt32LE(pos + 20);
    const nameLen = b.readUInt16LE(pos + 28);
    const extraLen = b.readUInt16LE(pos + 30);
    const commentLen = b.readUInt16LE(pos + 32);
    const local = b.readUInt32LE(pos + 42);
    const name = b.toString('utf8', pos + 46, pos + 46 + nameLen);
    const dataStart = local + 30 + b.readUInt16LE(local + 26) + b.readUInt16LE(local + 28);
    const raw = b.subarray(dataStart, dataStart + size);
    out.set(name, method === 8 ? inflateRawSync(raw) : Buffer.from(raw));
    pos += 46 + nameLen + extraLen + commentLen;
  }
  return out;
}

function zip(entries) {
  const locals = [];
  const central = [];
  let offset = 0;
  for (const [name, data] of entries) {
    const nameBuf = Buffer.from(name);
    const comp = deflateRawSync(data);
    const head = Buffer.alloc(30);
    head.writeUInt32LE(0x04034b50, 0);
    head.writeUInt16LE(20, 4);
    head.writeUInt16LE(8, 8);
    head.writeUInt32LE(crc32(data), 14);
    head.writeUInt32LE(comp.length, 18);
    head.writeUInt32LE(data.length, 22);
    head.writeUInt16LE(nameBuf.length, 26);
    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0);
    cd.writeUInt16LE(20, 4);
    cd.writeUInt16LE(20, 6);
    cd.writeUInt16LE(8, 10);
    cd.writeUInt32LE(crc32(data), 16);
    cd.writeUInt32LE(comp.length, 20);
    cd.writeUInt32LE(data.length, 24);
    cd.writeUInt16LE(nameBuf.length, 28);
    cd.writeUInt32LE(offset, 42);
    locals.push(head, nameBuf, comp);
    central.push(cd, nameBuf);
    offset += head.length + nameBuf.length + comp.length;
  }
  const cdBuf = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(entries.size, 8);
  end.writeUInt16LE(entries.size, 10);
  end.writeUInt32LE(cdBuf.length, 12);
  end.writeUInt32LE(offset, 16);
  return new Uint8Array(Buffer.concat([...locals, cdBuf, end]));
}

const ok = (r) => {
  assert.equal(r.ok, true, r.ok ? '' : r.problems.join(' | '));
  return r;
};

// ------------------------------------------------------------------ reading xlsx

test('IDs stay text: leading zeros, formatted zeros, long numbers', async () => {
  const file = await book((ws) => {
    ws.addRow(['Order no', 'Name']);
    ws.addRow(['000123', 'A']); // text cell with leading zeros
    ws.addRow([42, 'B']); // number shown as 00042 by its format
    ws.getCell('A3').numFmt = '00000';
    ws.addRow([123456789012, 'C']); // General: Excel would show 1.23457E+11
    ws.addRow(['12345678901234567890', 'D']); // 20-digit text, must not be rounded
  });
  const r = ok(await readSheet(file, { required: ['Order no', 'Name'], idColumns: ['Order no'] }));
  assert.deepEqual(r.rows.map((x) => x['Order no']), ['000123', '00042', '123456789012', '12345678901234567890']);
  assert.deepEqual(r.warnings, []);
});

test('a number of 16+ digits in an ID column is flagged as possibly damaged', async () => {
  const file = await book((ws) => {
    ws.addRow(['Id']);
    ws.addRow([1234567890123456]);
  });
  const r = ok(await readSheet(file, { required: ['Id'], idColumns: ['Id'] }));
  assert.equal(typeof r.rows[0].Id, 'string');
  assert.match(r.warnings.join('\n'), /16\+ digits/);
});

test('columns are found by header text in any order, case and spacing; keys use the spelling asked for', async () => {
  const file = await book((ws) => {
    ws.addRow(['Total', '  order NO ', 'Extra', 'Name']);
    ws.addRow([10.5, '007', 'x', 'A']);
  });
  const r = ok(await readSheet(file, { required: ['Order no', 'Name', 'total'], idColumns: ['Order no'] }));
  assert.deepEqual(r.rows, [{ total: 10.5, 'Order no': '007', Extra: 'x', Name: 'A' }]);
  assert.deepEqual(r.headers, ['total', 'Order no', 'Extra', 'Name']);
});

test('rows above the header row are skipped, and rowNumbers point at the real rows', async () => {
  const file = await book((ws) => {
    ws.addRow(['Bills 2024']);
    ws.addRow([]);
    ws.addRow(['Name', 'Amount']);
    ws.addRow(['A', 1]);
    ws.addRow([]);
    ws.addRow(['B', 2]);
  });
  const r = ok(await readSheet(file, { required: ['Name', 'Amount'] }));
  assert.deepEqual(r.rows, [{ Name: 'A', Amount: 1 }, { Name: 'B', Amount: 2 }]);
  assert.deepEqual(r.rowNumbers, [4, 6]);
});

test('a missing required header is reported by name with the columns that exist', async () => {
  const file = await book((ws) => {
    ws.addRow(['Name', 'Amount']);
    ws.addRow(['A', 1]);
  });
  const r = await readSheet(file, { required: ['Name', 'Due date'] });
  assert.equal(r.ok, false);
  assert.equal(r.problems.length, 1);
  assert.match(r.problems[0], /no column "Due date"/);
  assert.match(r.problems[0], /"Name", "Amount"/);
});

test('a header that appears twice is a problem, not a silent pick', async () => {
  const file = await book((ws) => {
    ws.addRow(['Name', 'Amount', 'amount ']);
    ws.addRow(['A', 1, 2]);
  });
  const r = await readSheet(file, { required: ['Name', 'Amount'] });
  assert.equal(r.ok, false);
  assert.match(r.problems[0], /"Amount" more than once \(columns B, C\)/);
});

test('a merged header cell is refused with the cell named', async () => {
  const file = await book((ws) => {
    ws.addRow(['Name', 'Amount', '']);
    ws.mergeCells('B1:C1');
    ws.addRow(['A', 1, 2]);
  });
  const r = await readSheet(file, { required: ['Name', 'Amount'] });
  assert.equal(r.ok, false);
  assert.match(r.problems.join(' '), /B1 is a merged cell across columns B to C/);
});

test('merged cells in the data read as empty below the top cell, with a warning', async () => {
  const file = await book((ws) => {
    ws.addRow(['Customer', 'Amount']);
    ws.addRow(['Acme', 1]);
    ws.addRow(['', 2]);
    ws.addRow(['', 3]);
    ws.mergeCells('A2:A4');
  });
  const r = ok(await readSheet(file, { required: ['Customer', 'Amount'] }));
  assert.deepEqual(r.rows.map((x) => x.Customer), ['Acme', null, null]);
  assert.match(r.warnings.join(' '), /merged cells/);
});

test('formula cells give the saved result and are flagged; a formula never calculated is a warning', async () => {
  const file = await book((ws) => {
    ws.addRow(['Net', 'Gross', 'Later']);
    ws.addRow([100, { formula: 'A2*1.2', result: 120 }, { formula: 'A2*2' }]);
  });
  const r = ok(await readSheet(file, { required: ['Net', 'Gross', 'Later'] }));
  assert.deepEqual(r.rows, [{ Net: 100, Gross: 120, Later: null }]);
  assert.deepEqual(r.formulaCells, [{ row: 2, column: 'Gross' }, { row: 2, column: 'Later' }]);
  assert.match(r.warnings.join(' '), /no saved result/);
});

test('an Excel error value becomes empty with a warning', async () => {
  const file = await book((ws) => {
    ws.addRow(['A']);
    ws.addRow([{ formula: '1/0', result: { error: '#DIV/0!' } }]);
  });
  const r = ok(await readSheet(file, { required: ['A'] }));
  assert.deepEqual(r.rows, [{ A: null }]);
  assert.match(r.warnings.join(' '), /#DIV\/0!/);
});

test('dates come out as ISO text: date only, or with a time', async () => {
  const file = await book((ws) => {
    ws.addRow(['When', 'Due']);
    ws.addRow([new Date(Date.UTC(2024, 2, 5)), new Date(Date.UTC(2024, 11, 31, 14, 30, 0))]);
    ws.getCell('A2').numFmt = 'dd.mm.yyyy';
    ws.getCell('B2').numFmt = 'yyyy-mm-dd hh:mm';
  });
  const r = ok(await readSheet(file, { required: ['When', 'Due'], dateColumns: ['When', 'Due'] }));
  assert.deepEqual(r.rows, [{ When: '2024-03-05', Due: '2024-12-31T14:30:00' }]);
});

test('text dates and text numbers in typed columns are converted; junk is emptied with a warning', async () => {
  const file = await book((ws) => {
    ws.addRow(['When', 'Amount']);
    ws.addRow(['05.03.2024', '1.234,50']);
    ws.addRow(['not a date', 'abc']);
  });
  const r = ok(await readSheet(file, { required: [], dateColumns: ['When'], numberColumns: ['Amount'] }));
  assert.deepEqual(r.rows, [{ When: '2024-03-05', Amount: 1234.5 }, { When: null, Amount: null }]);
  assert.equal(r.warnings.length, 2);
});

test('the sheet with the wanted headers is chosen, not just the first one', async () => {
  const wb = new ExcelJS.Workbook();
  wb.addWorksheet('Cover').addRow(['Read me']);
  const data = wb.addWorksheet('Data');
  data.addRow(['Name']);
  data.addRow(['A']);
  const r = ok(await readSheet(new Uint8Array(await wb.xlsx.writeBuffer()), { required: ['Name'] }));
  assert.equal(r.sheetName, 'Data');
  const missing = await readSheet(new Uint8Array(await wb.xlsx.writeBuffer()), { required: ['Name'], sheet: 'Nope' });
  assert.equal(missing.ok, false);
  assert.match(missing.problems[0], /no sheet called "Nope".*"Cover", "Data"/);
});

test('hidden rows and data under a headerless column are reported', async () => {
  const file = await book((ws) => {
    ws.addRow(['Name', '']);
    ws.addRow(['A', 'stray']);
    ws.addRow(['B', '']);
    ws.getRow(3).hidden = true;
  });
  const r = ok(await readSheet(file, { required: ['Name'] }));
  assert.equal(r.rows.length, 2);
  assert.match(r.warnings.join(' '), /1 row\(s\) are hidden/);
  assert.match(r.warnings.join(' '), /Column\(s\) B have data but no header/);
});

test('not an xlsx: old .xls, plain junk, empty, a damaged zip, a zip that claims a huge size', async () => {
  const old = await readSheet(new Uint8Array([0xd0, 0xcf, 0x11, 0xe0, 0, 0, 0, 0]), { required: [] });
  assert.equal(old.ok, false);
  assert.match(old.problems[0], /old Excel file \(\.xls\) or a password-protected/);
  assert.equal((await readSheet(new Uint8Array(), { required: [] })).ok, false);
  assert.equal((await readSheet(bytes('PK-but-not-really'), { required: [] })).ok, false);

  const good = await book((ws) => ws.addRow(['A']));
  const bomb = Buffer.from(good);
  const cd = bomb.lastIndexOf(Buffer.from([0x50, 0x4b, 0x01, 0x02]));
  bomb.writeUInt32LE(0x7fffffff, cd + 24); // the directory now says this part unpacks to 2 GB
  const r = await readSheet(new Uint8Array(bomb), { required: [] });
  assert.equal(r.ok, false);
  assert.match(r.problems[0], /too much to open safely/);
});

test('a warning from the library while opening stops the read', async () => {
  const good = await book((ws) => ws.addRow(['A']), 'Data');
  const parts = unzip(good);
  const xml = parts.get('xl/workbook.xml').toString();
  parts.set('xl/workbook.xml', Buffer.from(xml.replace('name="Data"', `name="${'x'.repeat(40)}"`)));
  const r = await readSheet(zip(parts), { required: ['A'] });
  assert.equal(r.ok, false);
  assert.match(r.problems[0], /library warned/);
});

// ------------------------------------------------------------------ csv

test('German CSV: semicolons, comma decimals, quoted fields, BOM, dotted dates', () => {
  const text = '\uFEFFRechnung;Betrag;Datum;Notiz\r\n' + '00123;1.234,50;05.03.2024;"Text; mit ""Zitat"""\r\n' + '00124;7,5;06.03.2024;"zwei\r\nZeilen"\r\n';
  const r = ok(readCsv(bytes(text), { required: ['Rechnung', 'Betrag'], idColumns: ['Rechnung'], numberColumns: ['Betrag'], dateColumns: ['Datum'] }));
  assert.equal(r.delimiter, ';');
  assert.equal(r.decimal, ',');
  assert.deepEqual(r.rows, [
    { Rechnung: '00123', Betrag: 1234.5, Datum: '2024-03-05', Notiz: 'Text; mit "Zitat"' },
    { Rechnung: '00124', Betrag: 7.5, Datum: '2024-03-06', Notiz: 'zwei\r\nZeilen' },
  ]);
  assert.deepEqual(r.rowNumbers, [2, 3]);
  assert.deepEqual(r.warnings, []);
});

test('English CSV with commas and points is detected as such', () => {
  const r = ok(readCsv(bytes('id,amount\n007,"1,234.50"\n008,3.25\n'), { required: ['id', 'amount'], idColumns: ['id'], numberColumns: ['amount'] }));
  assert.equal(r.delimiter, ',');
  assert.equal(r.decimal, '.');
  assert.deepEqual(r.rows, [{ id: '007', amount: 1234.5 }, { id: '008', amount: 3.25 }]);
});

test('an ambiguous number (1,234) follows the delimiter style; a file that mixes styles is refused', () => {
  const de = ok(readCsv(bytes('a;n\nx;1,234\n'), { required: ['a'], numberColumns: ['n'] }));
  assert.equal(de.rows[0].n, 1.234);
  const mixed = readCsv(bytes('a;n\nx;1,5\ny;1.5\n'), { required: ['a'], numberColumns: ['n'] });
  assert.equal(mixed.ok, false);
  assert.match(mixed.problems[0], /mix two styles/);
});

test('CSV: an "sep=;" line, a tab file, ragged rows and blank lines', () => {
  const sep = ok(readCsv(bytes('sep=;\nname;qty\nA;1\n'), { required: ['name'] }));
  assert.deepEqual(sep.rows, [{ name: 'A', qty: '1' }]);
  const tab = ok(readCsv(bytes('name\tqty\nA\t1\n\nB\t2\textra\n'), { required: ['name'] }));
  assert.equal(tab.delimiter, '\t');
  assert.deepEqual(tab.rows.map((r) => r.name), ['A', 'B']);
  assert.match(tab.warnings.join(' '), /more values than the header/);
});

test('CSV: text that is not UTF-8 is read as Windows-1252 with a warning', () => {
  const latin1 = Uint8Array.from([...bytes('name;n\n'), ...[0x4d, 0xfc, 0x6c, 0x6c, 0x65, 0x72], ...bytes(';1\n')]); // "Müller"
  const r = ok(readCsv(latin1, { required: ['name'] }));
  assert.equal(r.rows[0].name, 'Müller');
  assert.match(r.warnings[0], /Windows-1252/);
});

test('CSV: missing header and an unclosed quote are reported', () => {
  const r = readCsv(bytes('a;b\n1;2\n'), { required: ['a', 'c'] });
  assert.equal(r.ok, false);
  assert.match(r.problems[0], /no column "c"/);
  const q = readCsv(bytes('a;b\n"1;2\n'), { required: ['a'] });
  assert.equal(q.ok, false);
  assert.match(q.problems[0], /never closed/);
});

test('readTable picks csv or xlsx by the bytes, not the name', async () => {
  const x = await book((ws) => {
    ws.addRow(['Name']);
    ws.addRow(['A']);
  });
  assert.equal(ok(await readTable(x, { required: ['Name'] })).sheetName, 'Bills');
  assert.equal(ok(await readTable(bytes('Name\nA\n'), { required: ['Name'] })).delimiter, ',');
});

test('parseNumber and parseDate', () => {
  assert.equal(parseNumber('1.234.567,89', ','), 1234567.89);
  assert.equal(parseNumber('1,234,567.89', '.'), 1234567.89);
  assert.equal(parseNumber('-3,5', ','), -3.5);
  assert.equal(parseNumber('1 234,5', ','), 1234.5);
  assert.equal(parseNumber('12,34,56', ','), null);
  assert.equal(parseNumber('1.5', ','), null); // a point is not a decimal mark here
  assert.equal(parseNumber('abc', '.'), null);
  assert.equal(parseNumber('', '.'), null);
  assert.equal(parseDate('2024-03-05'), '2024-03-05');
  assert.equal(parseDate('5.3.2024'), '2024-03-05');
  assert.equal(parseDate('31.02.2024'), null);
  assert.equal(parseDate('03/04/2024'), null); // day or month first? never guess
  assert.equal(parseDate('03/04/2024', 'dmy'), '2024-04-03');
  assert.equal(parseDate('03/04/2024', 'mdy'), '2024-03-04');
  assert.equal(parseDate('13/04/2024'), '2024-04-13');
});

// ------------------------------------------------------------------ writing

const COLUMNS = [
  { header: 'Order no', type: 'id' },
  { header: 'Name' },
  { header: 'Amount', type: 'number', numFmt: '#,##0.00' },
  { header: 'Due', type: 'date' },
];
const ROWS = [
  { 'Order no': '000123', Name: 'Müller & Söhne', Amount: 1234.5, Due: '2024-03-05' },
  { 'Order no': '123456789012345678', Name: '=SUM(A1)', Amount: -3, Due: '2024-12-31T14:30:00' },
  { 'Order no': '7', Name: null, Amount: null, Due: null },
];

test('round trip: write then read gives the same rows, and the cells have the right types', async () => {
  const file = await writeSheet(ROWS, COLUMNS, { sheetName: 'Bills: 2024' });
  const r = ok(await readSheet(file, { required: ['Order no', 'Name', 'Amount', 'Due'], idColumns: ['Order no'], dateColumns: ['Due'] }));
  assert.deepEqual(r.rows, ROWS);
  assert.equal(r.sheetName, 'Bills- 2024'); // the colon is not allowed in a sheet name
  assert.deepEqual(r.warnings, []);

  // Look at the XML itself, since no Excel is at hand.
  const parts = unzip(file);
  const sheet = parts.get('xl/worksheets/sheet1.xml').toString();
  const shared = parts.get('xl/sharedStrings.xml').toString();
  const cell = (ref) => new RegExp(`<c r="${ref}"([^>]*)>(.*?)</c>`).exec(sheet);
  for (const ref of ['A2', 'A3', 'A4']) assert.match(cell(ref)[1], /t="s"/, `${ref} must be a string cell`);
  assert.match(shared, /000123/);
  assert.match(shared, /123456789012345678/);
  assert.doesNotMatch(cell('C2')[1], /t="/); // a number cell has no type attribute
  assert.match(cell('C2')[2], /<v>1234\.5<\/v>/);
  assert.doesNotMatch(cell('D2')[1], /t="/); // a real date is a number with a date format
  assert.match(cell('D2')[2], /<v>45356<\/v>/); // 2024-03-05
  assert.match(sheet, /<pane[^>]*state="frozen"/);
  assert.match(sheet, /<pane[^>]*ySplit="1"/);
  assert.match(sheet, /<autoFilter ref="A1:D1"/);
  assert.match(sheet, /<col min="1" max="1" width="[\d.]+"/);
  assert.match(parts.get('xl/styles.xml').toString(), /yyyy-mm-dd/);
});

test('writeSheet refuses a value that does not fit its column, naming row and column', async () => {
  await assert.rejects(writeSheet([{ A: 'x' }], [{ header: 'A', type: 'number' }]), /Row 1, column "A": "x" is not a number/);
  await assert.rejects(writeSheet([{ A: 'soon' }], [{ header: 'A', type: 'date' }]), /is not a date/);
  await assert.rejects(writeSheet([], []), /No columns/);
});

test('an empty list of rows still writes a valid sheet with the header row', async () => {
  const r = ok(await readSheet(await writeSheet([], [{ header: 'Name' }]), { required: ['Name'] }));
  assert.deepEqual(r.rows, []);
});

test('CSV write: BOM, CRLF, quoting, comma decimals, formulas defused; reads back', () => {
  const file = writeCsv(ROWS, COLUMNS, { delimiter: ';', decimal: ',' });
  assert.deepEqual([...file.subarray(0, 3)], [0xef, 0xbb, 0xbf]);
  const text = new TextDecoder().decode(file.subarray(3));
  assert.equal(text.split('\r\n')[0], 'Order no;Name;Amount;Due');
  assert.equal(text.split('\r\n')[1], "000123;Müller & Söhne;1234,5;2024-03-05");
  assert.match(text.split('\r\n')[2], /;'=SUM\(A1\);-3;2024-12-31 14:30:00$/);
  assert.ok(text.endsWith('\r\n'));
  const back = ok(readCsv(file, { required: ['Order no'], idColumns: ['Order no'], numberColumns: ['Amount'] }));
  assert.equal(back.delimiter, ';');
  assert.equal(back.rows[0]['Order no'], '000123');
  assert.equal(back.rows[0].Amount, 1234.5);
  const quoted = writeCsv([{ A: 'a;b', B: 'say "hi"', C: 'two\nlines', D: ' padded' }], ['A', 'B', 'C', 'D'].map((header) => ({ header })), { delimiter: ';' });
  assert.equal(new TextDecoder().decode(quoted.subarray(3)), 'A;B;C;D\r\n"a;b";"say ""hi""";"two\nlines";" padded"\r\n');
});

// ------------------------------------------------------------------ rows from the page

test('checkRows accepts plain rows and rejects anything else', () => {
  assert.deepEqual(checkRows([{ a: 'x', b: 1, c: true, d: null, e: undefined }]), { ok: true, rows: [{ a: 'x', b: 1, c: true, d: null, e: null }] });
  assert.equal(checkRows('nope').ok, false);
  assert.equal(checkRows([1]).ok, false);
  assert.equal(checkRows([[1]]).ok, false);
  assert.equal(checkRows([{ a: { deep: 1 } }]).ok, false);
  assert.equal(checkRows([{ a: NaN }]).ok, false);
  assert.equal(checkRows([{}, {}], 1).ok, false);
});

test('a sheet or csv over maxRows is refused', async () => {
  const csv = readCsv(bytes('a\n1\n2\n3\n'), { required: ['a'], maxRows: 2 });
  assert.equal(csv.ok, false);
  assert.match(csv.problems[0], /more than 2 rows/);
  const file = await book((ws) => {
    ws.addRow(['a']);
    for (let i = 0; i < 3; i++) ws.addRow([i]);
  });
  const xlsx = await readSheet(file, { required: ['a'], maxRows: 2 });
  assert.equal(xlsx.ok, false);
  assert.match(xlsx.problems[0], /more than 2 rows/);
});

test('CSV saved by Excel as "Unicode text" (UTF-16 with BOM, tabs) is read', () => {
  const body = Buffer.from('\uFEFFname\tqty\r\nÄpfel\t3\r\n', 'utf16le');
  const r = ok(readCsv(new Uint8Array(body), { required: ['name'] }));
  assert.equal(r.delimiter, '\t');
  assert.deepEqual(r.rows, [{ name: 'Äpfel', qty: '3' }]);
});
